1	using System;
2	using System.Linq;
3	using Common.Debug;
4	using Core.Master;
5	using Core.Update;
6	using Game.Context;
7	using Game.Map;
8	using Game.Map.Interface.MapObject;
9	using Game.PlayerInventory.Interface;
10	using MessagePack;
11	using Microsoft.Extensions.DependencyInjection;
12	using NUnit.Framework;
13	using Server.Boot;
14	using Server.Protocol;
15	using Tests.Module.TestMod;
16	using static Server.Protocol.PacketResponse.MapObjectAcquisitionProtocol;
17	
18	namespace Tests.CombinedTest.Server.PacketTest
19	{
20	    /// <summary>
21	    ///     採掘のダメージ算出とクールダウンをサーバが握っていることを検証する
22	    ///     Verifies that the server owns mining damage resolution and the cooldown
23	    /// </summary>
24	    public class MapObjectAcquisitionProtocolTest
25	    {
26	        private const int PlayerId = 0;
27	
28	        // テストマスタのMining型mapObject(hp30 / damage7 / attackSpeed0.2)とその対応ツール
29	        // The Mining-type mapObject in the test master (hp30 / damage7 / attackSpeed0.2) and its matching tool
30	        private static readonly Guid MiningMapObjectGuid = Guid.Parse("00000000-0000-2222-0000-000000000001");
31	        private static readonly Guid PickUpMapObjectGuid = Guid.Parse("8c0e1339-be75-4690-99cd-58b5385a17cd");
32	        private static readonly Guid ToolItemGuid = Guid.Parse("00000000-0000-0000-1234-000000000001");
33	
34	        // TestMiningRockのminingToolsには無いアイテム
35	        // An item absent from TestMiningRock's miningTools
36	        private static readonly Guid UnmatchedToolItemGuid = Guid.Parse("00000000-0000-0000-1234-000000000004");
37	
38	        private const int ExpectedToolDamage = 7;
39	        private const double ExpectedAttackSpeed = 0.2;
40	
41	        [SetUp]
42	        public void SetUp()
43	        {
44	            // 高速採掘フラグを各テスト開始前にも除去し、前回異常終了の残置を隔離する
45	            // Remove the super-mine flag before each test too, isolating residue from an aborted prior test
46	            DebugParameters.RemoveBool(DebugParameterKeys.MapObjectSuperMine);
47	        }
48	
49	        [TearDown]
50	        public void TearDown()
51	        {
52	            // 高速採掘フラグの残置は他テストを無言で壊すため必ず消す
53	            // A leftover super-mine flag silently breaks other tests, so always remove it
54	            DebugParameters.RemoveBool(DebugParameterKeys.MapObjectSuperMine);
55	        }
56	
57	        [Test]
58	        public void 素手では掘れず対応ツール装備時のみdamage分HPが減り閾値未達では報酬が入らない()
59	        {
60	            var (packet, serviceProvider) = new MoorestechServerDIContainerGenerator().Create(new MoorestechServerDIContainerOptions(TestModDirectory.ForUnitTestModDirectory));
61	            var playerInventory = serviceProvider.GetService<IPlayerInventoryDataStore>().GetInventoryData(PlayerId);
62	            var mapObject = GetMapObject(MiningMapObjectGuid);
63	            var initialHp = mapObject.CurrentHp;
64	
65	            // 素手のままではサーバがダメージを解決できずHPは変化しない
66	            // With bare hands the server resolves no damage, so HP stays untouched
67	            SendAttack(packet, mapObject.InstanceId);
68	            Assert.AreEqual(initialHp, mapObject.CurrentHp);
69	
70	            // 対応ツールを装備して選択するとマスタのdamage分だけHPが減る
71	            // Equipping and selecting the matching tool reduces HP by the master-defined damage
72	            EquipTool(playerInventory, ToolItemGuid);
73	            SendAttack(packet, mapObject.InstanceId);
74	            Assert.AreEqual(initialHp - ExpectedToolDamage, mapObject.CurrentHp);
75	
76	            // HP30→23はearnItemHpIntervalの閾値20に届かないため報酬アイテムは入らない
77	            // HP 30->23 falls short of the earnItemHpInterval threshold 20, so no reward items arrive
78	            var earnItemId = GetEarnItemId(MiningMapObjectGuid);
79	            Assert.AreEqual(0, CountMainInventoryItem(playerInventory, earnItemId));
80	        }
81	
82	        [Test]
83	        public void 対応しないツールを装備してもHPは減らず報酬も入らない()
84	        {
85	            var (packet, serviceProvider) = new MoorestechServerDIContainerGenerator().Create(new MoorestechServerDIContainerOptions(TestModDirectory.ForUnitTestModDirectory));
86	            var playerInventory = serviceProvider.GetService<IPlayerInventoryDataStore>().GetInventoryData(PlayerId);
87	            var mapObject = GetMapObject(MiningMapObjectGuid);
88	            var initialHp = mapObject.CurrentHp;
89	
90	            // miningToolsに無いアイテムを装備してもどのdamageにも解決されずHPは変化しない
91	            // An item absent from miningTools resolves to no damage, so HP stays untouched
92	            EquipTool(playerInventory, UnmatchedToolItemGuid);
93	            SendAttack(packet, mapObject.InstanceId);
94	            Assert.AreEqual(initialHp, mapObject.CurrentHp);
95	            Assert.AreEqual(0, CountMainInventoryItem(playerInventory, GetEarnItemId(MiningMapObjectGuid)));
96	
97	            // 同じmapObjectでも対応ツールへ持ち替えれば掘れることまで確かめる
98	            // Confirm the same mapObject is still mineable once the matching tool is equipped
99	            EquipTool(playerInventory, ToolItemGuid);
100	            SendAttackAfterCooldown(packet, mapObject.InstanceId);
101	            Assert.AreEqual(initialHp - ExpectedToolDamage, mapObject.CurrentHp);
102	        }
103	
104	        [Test]
105	        public void 閾値を跨いだ回数だけ報酬アイテムが入る()
106	        {
107	            var (packet, serviceProvider) = new MoorestechServerDIContainerGenerator().Create(new MoorestechServerDIContainerOptions(TestModDirectory.ForUnitTestModDirectory));
108	            var playerInventory = serviceProvider.GetService<IPlayerInventoryDataStore>().GetInventoryData(PlayerId);
109	            var mapObject = GetMapObject(MiningMapObjectGuid);
110	            var earnItemId = GetEarnItemId(MiningMapObjectGuid);
111	            EquipTool(playerInventory, ToolItemGuid);
112	
113	            // 1打目はHP30→23で閾値20に未達なのでアイテムは入らない
114	            // The first hit takes HP 30->23 and misses threshold 20, so no items arrive
115	            SendAttack(packet, mapObject.InstanceId);
116	            Assert.AreEqual(0, CountMainInventoryItem(playerInventory, earnItemId));
117	
118	            // 2打目でHP16となり閾値20を1回跨ぐ
119	            // The second hit reaches HP 16 and crosses threshold 20 once
120	            SendAttackAfterCooldown(packet, mapObject.InstanceId);
121	            Assert.AreEqual(1, CountMainInventoryItem(playerInventory, earnItemId));
122	
123	            // 3打目でHP9となり閾値10も跨ぎ累計2回分になる
124	            // The third hit reaches HP 9 and crosses threshold 10, totalling two rewards
125	            SendAttackAfterCooldown(packet, mapObject.InstanceId);
126	            Assert.AreEqual(2, CountMainInventoryItem(playerInventory, earnItemId));
127	        }
128	
129	        [Test]
130	        public void attackSpeed未満の連打は無視される()
131	        {
132	            var (packet, serviceProvider) = new MoorestechServerDIContainerGenerator().Create(new MoorestechServerDIContainerOptions(TestModDirectory.ForUnitTestModDirectory));
133	            var playerInventory = serviceProvider.GetService<IPlayerInventoryDataStore>().GetInventoryData(PlayerId);
134	            var mapObject = GetMapObject(MiningMapObjectGuid);
135	            var initialHp = mapObject.CurrentHp;
136	            EquipTool(playerInventory, ToolItemGuid);
137	
138	            // 1打目は通り、直後の2打目はクールダウンで捨てられる
139	            // The first hit lands and the immediate second hit is dropped by the cooldown
140	            SendAttack(packet, mapObject.InstanceId);
141	            SendAttack(packet, mapObject.InstanceId);
142	            Assert.AreEqual(initialHp - ExpectedToolDamage, mapObject.CurrentHp);
143	
144	            // attackSpeed分のtickを進めれば次の打撃は再び通る
145	            // After advancing attackSpeed worth of ticks the next hit lands again
146	            AdvanceCooldown();
147	            SendAttack(packet, mapObject.InstanceId);
148	            Assert.AreEqual(initialHp - ExpectedToolDamage * 2, mapObject.CurrentHp);
149	        }
150	
151	        [Test]
152	        public void 同じプレイヤーは別mapObjectへ切り替えてもクールダウンを共有する()
153	        {
154	            var (_, serviceProvider) = new MoorestechServerDIContainerGenerator()
155	                .Create(new MoorestechServerDIContainerOptions(TestModDirectory.ForUnitTestModDirectory));
156	            var playerInventory = serviceProvider.GetService<IPlayerInventoryDataStore>().GetInventoryData(PlayerId);
157	            var miningService = serviceProvider.GetService<MapObjectMiningService>();
158	            EquipTool(playerInventory, ToolItemGuid);
159	
160	            var first = GetMapObject(MiningMapObjectGuid);
161	            var second = new VanillaStaticMapObject(
162	                999, MiningMapObjectGuid, false, first.CurrentHp, first.Position + UnityEngine.Vector3.right);
163	            var secondInitialHp = second.CurrentHp;
164	
165	            // 対象変更後もプレイヤー単位で待機
166	            // Cooldown remains player-wide after changing targets
167	            Assert.AreEqual(MiningAttackResult.Success,
168	                miningService.TryAttack(PlayerId, first, playerInventory.EquipmentInventory.GetSelectedItem(), out _));
169	            Assert.AreEqual(MiningAttackResult.CooldownNotElapsed,
170	                miningService.TryAttack(PlayerId, second, playerInventory.EquipmentInventory.GetSelectedItem(), out _));
171	            Assert.AreEqual(secondInitialHp, second.CurrentHp);
172	        }
173	
174	        [Test]
175	        public void PickUpはツール不要で一撃取得()
176	        {
177	            var (packet, serviceProvider) = new MoorestechServerDIContainerGenerator().Create(new MoorestechServerDIContainerOptions(TestModDirectory.ForUnitTestModDirectory));
178	            var playerInventory = serviceProvider.GetService<IPlayerInventoryDataStore>().GetInventoryData(PlayerId);
179	            var mapObject = GetMapObject(PickUpMapObjectGuid);
180	
181	            // 素手のまま1回の打撃で破壊され、報酬アイテムがメインインベントリへ入る
182	            // A single bare-handed hit destroys it and the reward items land in the main inventory
183	            SendAttack(packet, mapObject.InstanceId);
